1	// Credential-forwarding Streamable-HTTP MCP sidecar.
2	//
3	// Same tool surface as the stdio server (imported, not forked, from ezpds-mcp),
4	// but served over HTTP and multi-caller. Each caller authenticates via OAuth
5	// against Custos (the sidecar is the MCP-spec resource server; Custos is the
6	// authorization server, ADR-0019); the caller's bearer rides each tool call to
7	// the PDS and nothing durable is cached (ADR-0024). The sidecar terminates only
8	// the transport + the OAuth resource metadata; all auth decisions stay in the
9	// PDS.
10	
11	import * as http from 'node:http';
12	import { randomUUID } from 'node:crypto';
13	import { realpathSync } from 'node:fs';
14	import { fileURLToPath } from 'node:url';
15	import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
16	import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
17	import { isInitializeRequest } from '@modelcontextprotocol/sdk/types.js';
18	import type { AuthInfo } from '@modelcontextprotocol/sdk/server/auth/types.js';
19	// The tool surface is single-sourced from the sibling stdio package. It is
20	// imported by relative path (not the `ezpds-mcp` package specifier) because both
21	// packages run TypeScript natively with no build step, and Node refuses to
22	// type-strip files resolved under `node_modules` — a package-specifier import of
23	// this `.ts` source would fail at runtime. The relative path reaches the real
24	// sibling directory, so a tool bugfix still lands once.
25	import { registerTools } from '../../mcp/src/tools.ts';
26	import { decodeJwtPayload } from '../../mcp/src/auth.ts';
27	import { loadConfig, type SidecarConfig } from './config.ts';
28	import { SessionRegistry } from './registry.ts';
29	import { callerSubject } from './session.ts';
30	import { log, redactError } from './log.ts';
31	
32	/** Thrown when a tool is invoked without an authenticated caller. */
33	export class UnauthenticatedError extends Error {
34	  constructor() {
35	    super(
36	      'This request is not authenticated. The hosted MCP sidecar forwards your own ' +
37	        'credential — complete the OAuth authorization against Custos and present a ' +
38	        'bearer token; the sidecar holds none on your behalf.',
39	    );
40	  }
41	}
42	
43	/**
44	 * Build an `AuthInfo` from a request's `Authorization: Bearer` header, or
45	 * `undefined` when there is none. The sidecar does not verify the token itself —
46	 * the PDS is the resource server and rejects an invalid token on the forwarded
47	 * call; here we only read the caller identity/scopes to key the session.
48	 */
49	export function authFromRequest(authorization: string | undefined): AuthInfo | undefined {
50	  if (!authorization) return undefined;
51	  const match = /^Bearer\s+(.+)$/i.exec(authorization.trim());
52	  if (!match) return undefined;
53	  const token = match[1]!.trim();
54	  if (!token) return undefined;
55	
56	  let scopes: string[] = [];
57	  // Best-effort read of the token's scope claim, purely to key/annotate the
58	  // in-memory session; the authoritative scope check happens in the PDS.
59	  try {
60	    const scope = decodeJwtPayload(token).scope;
61	    if (typeof scope === 'string' && scope) scopes = scope.split(' ');
62	  } catch {
63	    // opaque token — leave scopes empty
64	  }
65	  return { token, clientId: callerSubject(token), scopes };
66	}
67	
68	/** The MCP-spec protected-resource metadata pointing at Custos as the AS. */
69	function protectedResourceMetadata(config: SidecarConfig): Record<string, unknown> {
70	  return {
71	    resource: config.publicOrigin,
72	    // The client must reach the PUBLIC Custos URL, never the private forwarding
73	    // origin (which is unroutable from outside the Railway network).
74	    authorization_servers: [config.authServerOrigin],
75	  };
76	}
77	
78	// MCP JSON-RPC messages are tiny; a generous ceiling still stops an
79	// unauthenticated client from streaming an unbounded body into memory.
80	const MAX_BODY_BYTES = 1024 * 1024;
81	
82	// Bounds on the live-transport map: a hard cap plus idle expiry, so an
83	// abandoned MCP session cannot pin memory indefinitely.
84	const MAX_TRANSPORTS = 1024;
85	const TRANSPORT_IDLE_MS = 10 * 60_000;
86	
87	/** Thrown by `readBody` when a request body exceeds `MAX_BODY_BYTES`. */
88	class PayloadTooLargeError extends Error {}
89	
90	function readBody(req: http.IncomingMessage): Promise<string> {
91	  return new Promise((resolve, reject) => {
92	    const chunks: Buffer[] = [];
93	    let total = 0;
94	    let settled = false;
95	    req.on('data', (chunk: Buffer) => {
96	      if (settled) return;
97	      total += chunk.length;
98	      if (total > MAX_BODY_BYTES) {
99	        // Stop buffering immediately (memory stays bounded) and reject; the
100	        // caller sends 413. We do NOT destroy the socket here — that would reset
101	        // the connection before the 413 response can flush.
102	        settled = true;
103	        chunks.length = 0;
104	        reject(new PayloadTooLargeError());
105	        return;
106	      }
107	      chunks.push(chunk);
108	    });
109	    req.on('end', () => {
110	      if (!settled) {
111	        settled = true;
112	        resolve(Buffer.concat(chunks).toString('utf8'));
113	      }
114	    });
115	    req.on('error', (err) => {
116	      if (!settled) {
117	        settled = true;
118	        reject(err);
119	      }
120	    });
121	  });
122	}
123	
124	function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
125	  const payload = JSON.stringify(body);
126	  res.writeHead(status, { 'content-type': 'application/json' });
127	  res.end(payload);
128	}
129	
130	/**
131	 * Build the HTTP server around a fresh session registry. Returns the server and
132	 * the registry so tests can drive both; nothing is bound to a listening socket
133	 * until the caller calls `listen`.
134	 */
135	export function createSidecar(config: SidecarConfig): {
136	  server: http.Server;
137	  registry: SessionRegistry;
138	} {
139	  const registry = new SessionRegistry({ pdsOrigin: config.pdsOrigin });
140	
141	  // One transport (and MCP server) per live MCP session, keyed by the session
142	  // id the transport assigns on initialize. Bounded and idle-expired so an
143	  // abandoned client (one that never sends DELETE) cannot grow the map without
144	  // limit. All transports share the one registry.
145	  const transports = new Map<string, { transport: StreamableHTTPServerTransport; lastActivity: number }>();
146	
147	  function sweepIdleTransports(now: number): void {
148	    for (const [id, entry] of transports) {
149	      if (now - entry.lastActivity > TRANSPORT_IDLE_MS) {
150	        transports.delete(id);
151	        void entry.transport.close();
152	      }
153	    }
154	  }
155	
156	  function touch(id: string, now: number): void {
157	    const entry = transports.get(id);
158	    if (entry) entry.lastActivity = now;
159	  }
160	
161	  function newTransport(): StreamableHTTPServerTransport {
162	    const transport: StreamableHTTPServerTransport = new StreamableHTTPServerTransport({
163	      sessionIdGenerator: () => randomUUID(),
164	      enableJsonResponse: true,
165	      onsessioninitialized: (id) => {
166	        transports.set(id, { transport, lastActivity: Date.now() });
167	      },
168	    });
169	    transport.onclose = () => {
170	      if (transport.sessionId) transports.delete(transport.sessionId);
171	    };
172	    const mcp = new McpServer({ name: 'custos-mcp-sidecar', version: '0.1.0' });
173	    registerTools(mcp, (extra) => {
174	      const session = registry.resolve(extra?.authInfo);
175	      if (!session) throw new UnauthenticatedError();
176	      return session;
177	    });
178	    void mcp.connect(transport);
179	    return transport;
180	  }
181	
182	  const server = http.createServer((req, res) => {
183	    void handle(req, res).catch((err) => {
184	      log(`unhandled request error: ${redactError(err)}`);
185	      if (!res.headersSent) sendJson(res, 500, { error: 'internal error' });
186	    });
187	  });
188	
189	  async function handle(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
190	    const url = new URL(req.url ?? '/', config.publicOrigin);
191	
192	    if (req.method === 'GET' && url.pathname === '/.well-known/oauth-protected-resource') {
193	      sendJson(res, 200, protectedResourceMetadata(config));
194	      return;
195	    }
196	    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/healthz')) {
197	      sendJson(res, 200, { status: 'ok' });
198	      return;
199	    }
200	    if (url.pathname !== config.mcpPath) {
201	      sendJson(res, 404, { error: 'not found' });
202	      return;
203	    }
204	
205	    // Attach the caller's forwarded credential so the transport threads it into
206	    // each tool call's `extra.authInfo`. It is bound per request only — the
207	    // registry mints a fresh, request-scoped session and stores no credential.
208	    const auth = authFromRequest(req.headers['authorization']);
209	    (req as http.IncomingMessage & { auth?: AuthInfo }).auth = auth;
210	
211	    const now = Date.now();
212	    sweepIdleTransports(now);
213	    const sessionId = req.headers['mcp-session-id'];
214	    const existing = typeof sessionId === 'string' ? transports.get(sessionId)?.transport : undefined;
215	    if (typeof sessionId === 'string') touch(sessionId, now);
216	
217	    if (req.method === 'POST') {
218	      let raw: string;
219	      try {
220	        raw = await readBody(req);
221	      } catch (err) {
222	        if (err instanceof PayloadTooLargeError) {
223	          sendJson(res, 413, { error: 'request body too large' });
224	          return;
225	        }
226	        throw err;
227	      }
228	      let body: unknown;
229	      try {
230	        body = raw ? JSON.parse(raw) : undefined;
231	      } catch {
232	        sendJson(res, 400, { error: 'invalid JSON body' });
233	        return;
234	      }
235	      if (!existing && isInitializeRequest(body) && transports.size >= MAX_TRANSPORTS) {
236	        // At capacity: refuse new sessions rather than allocate past the bound.
237	        sendJson(res, 503, { error: 'sidecar at session capacity; retry shortly' });
238	        return;
239	      }
240	      const transport = existing ?? (isInitializeRequest(body) ? newTransport() : undefined);
241	      if (!transport) {
242	        sendJson(res, 400, { error: 'no valid MCP session; send an initialize request first' });
243	        return;
244	      }
245	      await transport.handleRequest(req, res, body);
246	      return;
247	    }
248	
249	    // GET (SSE stream) and DELETE (session teardown) require an existing session.
250	    if (!existing) {
251	      sendJson(res, 400, { error: 'unknown or missing MCP session id' });
252	      return;
253	    }
254	    await existing.handleRequest(req, res);
255	  }
256	
257	  return { server, registry };
258	}
259	
260	/**
261	 * True when this module is the process entry point. Compares realpaths so it
262	 * holds whether launched as `node src/server.ts` (relative argv), through the
263	 * bin wrapper (a `..`-containing path), or via an absolute path — not just the
264	 * exact-string form.
265	 */
266	function isMain(): boolean {
267	  const entry = process.argv[1];
268	  if (!entry) return false;
269	  try {
270	    return realpathSync(entry) === fileURLToPath(import.meta.url);
271	  } catch {
272	    return false;
273	  }
274	}
275	
276	// Entry point: bind the socket. Skipped when imported by tests (which call
277	// createSidecar directly and listen on an ephemeral port).
278	if (isMain()) {
279	  const config = loadConfig();
280	  const { server } = createSidecar(config);
281	  server.listen(config.port, () => {
282	    log(`listening on :${config.port}${config.mcpPath} — forwarding to ${config.pdsOrigin}`);
283	    log(`resource identifier: ${config.publicOrigin}`);
284	  });
285	}
286

