1	// The MCP tool surface: a deliberately small set matching the default agent
2	// scope profile (repo create/update + blob upload + AppView reads). Every tool
3	// runs as the agent registration the user confirmed — writes are attributed to
4	// it and visible in the user's audit log.
5	//
6	// put_record and delete_record are registered only when the operator sets
7	// CUSTOS_MCP_ALLOW_DESTRUCTIVE; with it unset they do not appear in the tool
8	// list at all.
9	
10	import * as fs from 'node:fs';
11	import * as path from 'node:path';
12	import { z } from 'zod';
13	import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
14	import type { AuthInfo } from '@modelcontextprotocol/sdk/server/auth/types.js';
15	import { xrpc, HttpError } from './http.ts';
16	import { RevokedError, SessionExpiredError, type SessionState } from './auth.ts';
17	import { ALLOW_DESTRUCTIVE, imageDir } from './config.ts';
18	
19	/**
20	 * The slice of a session the tool surface actually consumes. `AgentSession`
21	 * (the stdio server's onboarding-and-cache unit) satisfies it structurally, and
22	 * so does the sidecar's per-request forwarding session — that is what lets both
23	 * entry points single-source these tool implementations.
24	 */
25	export interface SessionLike {
26	  readonly pdsUrl: string;
27	  accessToken(): Promise<string>;
28	  did(): string | null;
29	  scopes(): string[];
30	  status(): SessionState;
31	}
32	
33	/**
34	 * Resolves the session a tool call runs as. The stdio server binds one
35	 * singleton (`() => session`); the sidecar resolves a per-caller forwarding
36	 * session from the request's authenticated identity (`extra.authInfo`). A tool
37	 * handler is invoked with the MCP `extra` object, which carries `authInfo` when
38	 * the transport authenticated the caller.
39	 */
40	export type SessionResolver = (extra?: { authInfo?: AuthInfo }) => SessionLike;
41	
42	const ATTRIBUTION =
43	  'Runs as this MCP server’s agent registration: the action is attributed to the agent ' +
44	  'and visible in the account owner’s audit log.';
45	
46	type ToolResult = {
47	  content: { type: 'text'; text: string }[];
48	  isError?: boolean;
49	};
50	
51	function ok(data: unknown): ToolResult {
52	  return { content: [{ type: 'text', text: JSON.stringify(data, null, 2) }] };
53	}
54	
55	function fail(message: string): ToolResult {
56	  return { content: [{ type: 'text', text: message }], isError: true };
57	}
58	
59	/**
60	 * Translate transport/PDS failures into messages an MCP client can act on —
61	 * never a stack trace. Scope refusals name the missing permission and the
62	 * scopes the agent actually holds.
63	 */
64	function relayError(err: unknown, session: SessionLike): ToolResult {
65	  if (err instanceof RevokedError || err instanceof SessionExpiredError) {
66	    return fail(err.message);
67	  }
68	  if (err instanceof HttpError) {
69	    if (err.status === 403 && err.errorCode === 'InsufficientScope') {
70	      const scopes = session.scopes();
71	      return fail(
72	        `The PDS refused this action as outside the agent's granted scopes ` +
73	          `(403 InsufficientScope): ${err.errorDescription ?? 'no details'}. ` +
74	          `Granted scopes: ${scopes.length ? scopes.join(' ') : '(none recorded)'}. ` +
75	          `Widening what this agent may do requires the PDS operator to change ` +
76	          `[agent_auth] granted_scopes and the owner to re-confirm a claim ceremony.`,
77	      );
78	    }
79	    return fail(
80	      `The PDS rejected the request (HTTP ${err.status}` +
81	        `${err.errorCode ? `, ${err.errorCode}` : ''}): ` +
82	        `${err.errorDescription ?? 'no details provided'}`,
83	    );
84	  }
85	  return fail(err instanceof Error ? err.message : String(err));
86	}
87	
88	/**
89	 * Confine image reads to the operator-configured directory. Without this, a
90	 * tool call influenced by untrusted content could publish any file the
91	 * process can read. Realpaths on both sides so symlinks cannot escape.
92	 */
93	function resolveImagePath(userPath: string): string {
94	  const configured = imageDir();
95	  if (!configured) {
96	    throw new Error(
97	      'image attachments are disabled: set CUSTOS_MCP_IMAGE_DIR to the one directory ' +
98	        'images may be read from',
99	    );
100	  }
101	  const base = fs.realpathSync(path.resolve(configured));
102	  let resolved: string;
103	  try {
104	    resolved = fs.realpathSync(path.resolve(base, userPath));
105	  } catch {
106	    throw new Error(`image_path does not exist under ${base}`);
107	  }
108	  if (resolved !== base && !resolved.startsWith(base + path.sep)) {
109	    throw new Error(`image_path must be inside ${base}`);
110	  }
111	  return resolved;
112	}
113	
114	/** MIME type for uploaded post images, by file extension. */
115	function imageMime(filePath: string): string {
116	  const mime: Record<string, string> = {
117	    '.png': 'image/png',
118	    '.jpg': 'image/jpeg',
119	    '.jpeg': 'image/jpeg',
120	    '.gif': 'image/gif',
121	    '.webp': 'image/webp',
122	  };
123	  const ext = path.extname(filePath).toLowerCase();
124	  const type = mime[ext];
125	  if (!type) {
126	    throw new Error(`unsupported image type "${ext}" — use png, jpg, gif, or webp`);
127	  }
128	  return type;
129	}
130	
131	async function requireDid(session: SessionLike): Promise<{ token: string; did: string }> {
132	  const token = await session.accessToken();
133	  const did = session.did();
134	  if (!did) throw new Error('the agent session has no DID — onboarding did not complete');
135	  return { token, did };
136	}
137	
138	const replyRef = z.object({ uri: z.string(), cid: z.string() });
139	
140	export function registerTools(server: McpServer, resolveSession: SessionResolver): void {
141	  server.registerTool(
142	    'whoami',
143	    {
144	      description:
145	        'Report this MCP server’s onboarding status and identity on the PDS: state ' +
146	        '(onboarding / ready / revoked / expired), DID, handle, granted scopes, and — while ' +
147	        'a claim ceremony is pending — the user_code and verification URI the account owner ' +
148	        'must confirm. Use this first if any other tool reports an auth problem.',
149	      annotations: { readOnlyHint: true },
150	    },
151	    async (extra) => {
152	      const session = resolveSession(extra);
153	      const status = session.status();
154	      const report: Record<string, unknown> = { pds_url: session.pdsUrl, ...status };
155	      if (status.state === 'onboarding') {
156	        report.action_needed =
157	          `Ask the account owner to confirm claim code ${status.userCode} at ` +
158	          `${status.verificationUri} (or in the Obsign wallet).`;
159	      }
160	      if (status.state === 'ready') {
161	        try {
162	          const describe = await xrpc(session.pdsUrl, 'com.atproto.repo.describeRepo', {
163	            params: { repo: status.did },
164	          });
165	          report.handle = describe.handle;
166	        } catch {
167	          // handle is cosmetic; the status report is still useful without it
168	        }
169	      }
170	      return ok(report);
171	    },
172	  );
173	
174	  server.registerTool(
175	    'create_post',
176	    {
177	      description:
178	        `Publish an app.bsky.feed.post to the user’s repository — text, optional reply ` +
179	        `references, optional attached image (uploaded as a blob). ${ATTRIBUTION}`,
180	      annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false },
181	      inputSchema: {
182	        text: z.string().max(3000).describe('Post text'),
183	        reply: z
184	          .object({ root: replyRef, parent: replyRef })
185	          .optional()
186	          .describe('Reply references (uri+cid of the thread root and the parent post)'),
187	        image_path: z
188	          .string()
189	          .optional()
190	          .describe(
191	            'Image file to attach (png/jpg/gif/webp), as a path inside the directory ' +
192	              'configured by CUSTOS_MCP_IMAGE_DIR (attachments are disabled without it)',
193	          ),
194	        image_alt: z.string().optional().describe('Alt text for the attached image'),
195	        langs: z.array(z.string()).optional().describe('BCP-47 language tags'),
196	      },
197	    },
198	    async (args, extra) => {
199	      const session = resolveSession(extra);
200	      try {
201	        const { token, did } = await requireDid(session);
202	
203	        let embed: Record<string, unknown> | undefined;
204	        if (args.image_path) {
205	          const imagePath = resolveImagePath(args.image_path);
206	          const mimeType = imageMime(imagePath);
207	          const bytes = fs.readFileSync(imagePath);
208	          const uploaded = await xrpc(session.pdsUrl, 'com.atproto.repo.uploadBlob', {
209	            method: 'POST',
210	            token,
211	            headers: { 'Content-Type': mimeType },
212	            body: new Uint8Array(bytes),
213	          });
214	          embed = {
215	            $type: 'app.bsky.embed.images',
216	            images: [{ image: uploaded.blob, alt: args.image_alt ?? '' }],
217	          };
218	        }
219	
220	        const record: Record<string, unknown> = {
221	          $type: 'app.bsky.feed.post',
222	          text: args.text,
223	          createdAt: new Date().toISOString(),
224	        };
225	        if (args.reply) record.reply = args.reply;
226	        if (args.langs) record.langs = args.langs;
227	        if (embed) record.embed = embed;
228	
229	        const created = await xrpc(session.pdsUrl, 'com.atproto.repo.createRecord', {
230	          method: 'POST',
231	          token,
232	          body: { repo: did, collection: 'app.bsky.feed.post', record },
233	        });
234	        return ok(created);
235	      } catch (err) {
236	        return relayError(err, session);
237	      }
238	    },
239	  );
240	
241	  server.registerTool(
242	    'get_record',
243	    {
244	      description:
245	        'Read a single record from the user’s repository (or another repo by DID/handle) ' +
246	        'by collection and record key.',
247	      annotations: { readOnlyHint: true },
248	      inputSchema: {
249	        collection: z.string().describe('Collection NSID, e.g. app.bsky.feed.post'),
250	        rkey: z.string().describe('Record key'),
251	        repo: z
252	          .string()
253	          .optional()
254	          .describe('DID or handle of the repo to read (defaults to the onboarded account)'),
255	      },
256	    },
257	    async (args, extra) => {
258	      const session = resolveSession(extra);
259	      try {
260	        const repo = args.repo ?? session.did();
261	        if (!repo) throw new Error('no repo given and the agent session has no DID yet');
262	        const record = await xrpc(session.pdsUrl, 'com.atproto.repo.getRecord', {
263	          params: { repo, collection: args.collection, rkey: args.rkey },
264	        });
265	        return ok(record);
266	      } catch (err) {
267	        return relayError(err, session);
268	      }
269	    },
270	  );
271	
272	  server.registerTool(
273	    'list_records',
274	    {
275	      description:
276	        'List records in a collection of the user’s repository (or another repo by ' +
277	        'DID/handle), paginated by cursor.',
278	      annotations: { readOnlyHint: true },
279	      inputSchema: {
280	        collection: z.string().describe('Collection NSID, e.g. app.bsky.feed.post'),
281	        limit: z.number().int().min(1).max(100).optional().describe('Page size (default 50)'),
282	        cursor: z.string().optional().describe('Cursor from a previous page'),
283	        repo: z
284	          .string()
285	          .optional()
286	          .describe('DID or handle of the repo to read (defaults to the onboarded account)'),
287	      },
288	    },
289	    async (args, extra) => {
290	      const session = resolveSession(extra);
291	      try {
292	        const repo = args.repo ?? session.did();
293	        if (!repo) throw new Error('no repo given and the agent session has no DID yet');
294	        const records = await xrpc(session.pdsUrl, 'com.atproto.repo.listRecords', {
295	          params: {
296	            repo,
297	            collection: args.collection,
298	            limit: args.limit,
299	            cursor: args.cursor,
300	          },
301	        });
302	        return ok(records);
303	      } catch (err) {
304	        return relayError(err, session);
305	      }
306	    },
307	  );
308	
309	  server.registerTool(
310	    'search_timeline',
311	    {
312	      description:
313	        'Read the user’s timeline, or search posts when a query is given. Reads are ' +
314	        'proxied through the PDS to its configured AppView and attributed to the agent.',
315	      annotations: { readOnlyHint: true },
316	      inputSchema: {
317	        query: z
318	          .string()
319	          .optional()
320	          .describe('Search query (app.bsky.feed.searchPosts); omit to read the timeline'),
321	        limit: z.number().int().min(1).max(100).optional().describe('Number of results'),
322	        cursor: z.string().optional().describe('Cursor from a previous page'),
323	      },
324	    },
325	    async (args, extra) => {
326	      const session = resolveSession(extra);
327	      try {
328	        const token = await session.accessToken();
329	        const result = args.query
330	          ? await xrpc(session.pdsUrl, 'app.bsky.feed.searchPosts', {
331	              token,
332	              params: { q: args.query, limit: args.limit, cursor: args.cursor },
333	            })
334	          : await xrpc(session.pdsUrl, 'app.bsky.feed.getTimeline', {
335	              token,
336	              params: { limit: args.limit, cursor: args.cursor },
337	            });
338	        return ok(result);
339	      } catch (err) {
340	        return relayError(err, session);
341	      }
342	    },
343	  );
344	
345	  server.registerTool(
346	    'account_status',
347	    {
348	      description:
349	        'Report the onboarded account’s hosting status on the PDS: activation, repo ' +
350	        'head/rev, and record/blob counts (com.atproto.server.checkAccountStatus).',
351	      annotations: { readOnlyHint: true },
352	    },
353	    async (extra) => {
354	      const session = resolveSession(extra);
355	      try {
356	        const token = await session.accessToken();
357	        const status = await xrpc(session.pdsUrl, 'com.atproto.server.checkAccountStatus', {
358	          token,
359	        });
360	        return ok(status);
361	      } catch (err) {
362	        return relayError(err, session);
363	      }
364	    },
365	  );
366	
367	  if (!ALLOW_DESTRUCTIVE) return;
368	
369	  server.registerTool(
370	    'put_record',
371	    {
372	      description:
373	        `Create or overwrite a record at a specific collection + rkey in the user’s ` +
374	        `repository. Destructive (enabled by CUSTOS_MCP_ALLOW_DESTRUCTIVE). ${ATTRIBUTION}`,
375	      annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: true },
376	      inputSchema: {
