378	        rkey: z.string().describe('Record key to write'),
379	        record: z.record(z.string(), z.unknown()).describe('The full record value (JSON object)'),
380	      },
381	    },
382	    async (args, extra) => {
383	      const session = resolveSession(extra);
384	      try {
385	        const { token, did } = await requireDid(session);
386	        const result = await xrpc(session.pdsUrl, 'com.atproto.repo.putRecord', {
387	          method: 'POST',
388	          token,
389	          body: { repo: did, collection: args.collection, rkey: args.rkey, record: args.record },
390	        });
391	        return ok(result);
392	      } catch (err) {
393	        return relayError(err, session);
394	      }
395	    },
396	  );
397	
398	  server.registerTool(
399	    'delete_record',
400	    {
401	      description:
402	        `Delete a record from the user’s repository. Destructive (enabled by ` +
403	        `CUSTOS_MCP_ALLOW_DESTRUCTIVE); note the default agent scope profile does not include ` +
404	        `delete, so the PDS may refuse with 403 unless the operator granted it. ${ATTRIBUTION}`,
405	      annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: true },
406	      inputSchema: {
407	        collection: z.string().describe('Collection NSID'),
408	        rkey: z.string().describe('Record key to delete'),
409	      },
410	    },
411	    async (args, extra) => {
412	      const session = resolveSession(extra);
413	      try {
414	        const { token, did } = await requireDid(session);
415	        const result = await xrpc(session.pdsUrl, 'com.atproto.repo.deleteRecord', {
416	          method: 'POST',
417	          token,
418	          body: { repo: did, collection: args.collection, rkey: args.rkey },
419	        });
