1	// The auth.md onboarding flow and agent session lifecycle:
2	//
3	//   discover   GET /.well-known/oauth-protected-resource → AS metadata → auth.md
4	//   register   POST {identity_endpoint}  type=service_auth, login_hint=<email>
5	//   claim      surface user_code + verification_uri to the human, then poll
6	//              POST {token_endpoint}  grant_type=urn:workos:agent-auth:grant-type:claim
7	//   exchange   POST {token_endpoint}  grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer
8	//
9	// Agent access tokens are short-lived (~5 min) with no refresh token; the
10	// service-signed identity assertion is the durable credential and is
11	// re-exchanged transparently until it expires. Revocation in the wallet makes
12	// the exchange fail with access_denied — we then stop and require explicit
13	// user action (never auto-re-register).
14	
15	import { request, HttpError, sleep } from './http.ts';
16	import { loginEmail } from './config.ts';
17	import {
18	  loadCredentials,
19	  saveCredentials,
20	  clearCredentials,
21	  type CachedCredentials,
22	} from './state.ts';
23	
24	const CLAIM_GRANT = 'urn:workos:agent-auth:grant-type:claim';
25	const JWT_BEARER_GRANT = 'urn:ietf:params:oauth:grant-type:jwt-bearer';
26	
27	/** Thrown when the server says this registration was revoked. */
28	export class RevokedError extends Error {
29	  constructor() {
30	    super(
31	      'This agent was revoked in Obsign. It will not re-register itself: to onboard again, ' +
32	        'the account owner must run `custos-mcp reset` (or delete the cached-credentials file) ' +
33	        'and restart the server, then confirm the new claim ceremony.',
34	    );
35	  }
36	}
37	
38	/** Thrown when the identity assertion has expired and a new ceremony is needed. */
39	export class SessionExpiredError extends Error {
40	  constructor() {
41	    super(
42	      'The agent session has expired (the identity assertion outlived its TTL). ' +
43	        'A new claim ceremony has to be confirmed by the account owner — restart the ' +
44	        'MCP server to begin one, or call the whoami tool after restart for the claim code.',
45	    );
46	  }
47	}
48	
49	export interface Discovery {
50	  authorizationServer: string;
51	  tokenEndpoint: string;
52	  identityEndpoint: string;
53	  claimEndpoint: string;
54	  /** URL of the auth.md skill document. */
55	  skill: string | null;
56	  identityTypesSupported: string[];
57	}
58	
59	/** Decode a JWT payload without verifying — we only read our own credentials. */
60	export function decodeJwtPayload(jwt: string): Record<string, unknown> {
61	  const part = jwt.split('.')[1];
62	  if (!part) throw new Error('malformed JWT');
63	  return JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
64	}
65	
66	/**
67	 * The discovery walk from the auth.md spec: PRM names the authorization
68	 * server, its metadata carries the agent_auth block, which points at the
69	 * auth.md skill document and the agent endpoints.
70	 */
71	export async function discover(pdsUrl: string): Promise<Discovery> {
72	  const prm = await request(`${pdsUrl}/.well-known/oauth-protected-resource`);
73	  const authorizationServer: string = (prm.authorization_servers?.[0] ?? pdsUrl).replace(
74	    /\/+$/,
75	    '',
76	  );
77	
78	  const as = await request(`${authorizationServer}/.well-known/oauth-authorization-server`);
79	  const agentAuth = as.agent_auth;
80	  if (!agentAuth || !agentAuth.identity_endpoint) {
81	    throw new Error(
82	      `${pdsUrl} does not advertise agent authentication (no agent_auth block in its ` +
83	        'authorization-server metadata). This PDS cannot onboard agents via auth.md.',
84	    );
85	  }
86	
87	  return {
88	    authorizationServer,
89	    tokenEndpoint: as.token_endpoint,
90	    identityEndpoint: agentAuth.identity_endpoint,
91	    claimEndpoint: agentAuth.claim_endpoint,
92	    skill: agentAuth.skill ?? null,
93	    identityTypesSupported: agentAuth.identity_types_supported ?? [],
94	  };
95	}
96	
97	export interface RegistrationResult {
98	  registrationId: string;
99	  claimToken: string;
100	  userCode: string;
101	  verificationUri: string;
102	  expiresAt: string;
103	}
104	
105	/**
106	 * Register via the service_auth flow (email as login_hint). The server starts
107	 * a claim ceremony bound to the matching local account and hands back the
108	 * user_code the human must confirm.
109	 */
110	export async function registerServiceAuth(
111	  discovery: Discovery,
112	  email: string,
113	): Promise<RegistrationResult> {
114	  let response;
115	  try {
116	    response = await request(discovery.identityEndpoint, {
117	      method: 'POST',
118	      body: { type: 'service_auth', login_hint: email },
119	    });
120	  } catch (err) {
121	    if (err instanceof HttpError && err.errorCode?.endsWith('_not_enabled')) {
122	      throw new Error(
123	        `This PDS has the ${err.errorCode.replace('_not_enabled', '')} agent registration ` +
124	          `flow disabled (${err.errorCode}). Ask the operator to enable ` +
125	          `[agent_auth] service_auth_enabled, or check auth.md at ` +
126	          `${discovery.skill ?? 'the service root'} for supported flows.`,
127	      );
128	    }
129	    if (err instanceof HttpError && err.errorCode === 'access_denied') {
130	      throw new Error(
131	        `The PDS rejected registration: ${err.errorDescription ?? 'access denied'}. ` +
132	          `Check that CUSTOS_MCP_EMAIL (${email}) matches an account on this PDS.`,
133	      );
134	    }
135	    throw err;
136	  }
137	
138	  return {
139	    registrationId: response.registration_id,
140	    claimToken: response.claim_token,
141	    userCode: response.claim.user_code,
142	    verificationUri: response.claim.verification_uri,
143	    expiresAt: response.claim.expires_at,
144	  };
145	}
146	
147	export interface ClaimGrantResult {
148	  accessToken: string;
149	  expiresIn: number;
150	  scope: string;
151	  assertion: string;
152	  assertionExpires: string;
153	}
154	
155	/**
156	 * Poll the token endpoint with the claim grant until the human confirms.
157	 * Device-flow etiquette: wait `interval` between polls, add 5s on slow_down,
158	 * cap the backoff.
159	 */
160	export async function pollClaim(
161	  discovery: Discovery,
162	  claimToken: string,
163	  options: { intervalSecs?: number; onPending?: () => void } = {},
164	): Promise<ClaimGrantResult> {
165	  let interval = (options.intervalSecs ?? 5) * 1000;
166	  const maxInterval = 60_000;
167	
168	  for (;;) {
169	    await sleep(interval);
170	    try {
171	      const token = await request(discovery.tokenEndpoint, {
172	        method: 'POST',
173	        body: new URLSearchParams({ grant_type: CLAIM_GRANT, claim_token: claimToken }),
174	      });
175	      return {
176	        accessToken: token.access_token,
177	        expiresIn: token.expires_in,
178	        scope: token.scope ?? '',
179	        assertion: token.identity_assertion,
180	        assertionExpires: token.assertion_expires,
181	      };
182	    } catch (err) {
183	      if (!(err instanceof HttpError)) throw err;
184	      switch (err.errorCode) {
185	        case 'authorization_pending':
186	          options.onPending?.();
187	          continue;
188	        case 'slow_down':
189	          interval = Math.min(interval + 5_000, maxInterval);
190	          continue;
191	        case 'expired_token':
192	          throw new Error(
193	            'The claim ceremony expired before it was confirmed. Restart the MCP server ' +
194	              'to begin a new one.',
195	          );
196	        case 'access_denied':
197	          throw new RevokedError();
198	        default:
199	          throw err;
200	      }
201	    }
202	  }
203	}
204	
205	/**
206	 * Exchange the identity assertion for a fresh access token (RFC 7523
207	 * JWT-bearer grant). The token inherits the assertion's scopes verbatim.
208	 */
209	export async function exchangeAssertion(
210	  tokenEndpoint: string,
211	  assertion: string,
212	  resource: string,
213	): Promise<{ accessToken: string; expiresIn: number; scope: string }> {
214	  try {
215	    const token = await request(tokenEndpoint, {
216	      method: 'POST',
217	      body: new URLSearchParams({
218	        grant_type: JWT_BEARER_GRANT,
219	        assertion,
220	        resource: `${resource}/`,
221	      }),
222	    });
223	    return {
224	      accessToken: token.access_token,
225	      expiresIn: token.expires_in,
226	      scope: token.scope ?? '',
227	    };
228	  } catch (err) {
229	    if (err instanceof HttpError) {
230	      if (err.errorCode === 'access_denied') throw new RevokedError();
231	      if (err.errorCode === 'invalid_grant') throw new SessionExpiredError();
232	    }
233	    throw err;
234	  }
235	}
236	
237	export type SessionState =
238	  | { state: 'onboarding'; userCode: string; verificationUri: string; expiresAt: string }
239	  | { state: 'ready'; did: string; scopes: string[]; registrationId: string | null }
240	  | { state: 'revoked' }
241	  | { state: 'expired' }
242	  | { state: 'error'; message: string };
243	
244	/**
245	 * One agent session against one PDS. Owns the cached credentials, runs the
246	 * onboarding ceremony when there are none, and hands out a live access token
247	 * to the tool layer (re-exchanging the assertion transparently).
248	 */
249	export class AgentSession {
250	  readonly pdsUrl: string;
251	  private discovery: Discovery | null = null;
252	  private creds: CachedCredentials | null;
253	  private onboarding: RegistrationResult | null = null;
254	  private onboardingError: string | null = null;
255	
256	  constructor(pdsUrl: string) {
257	    this.pdsUrl = pdsUrl;
258	    this.creds = loadCredentials(pdsUrl);
259	  }
260	
261	  private async discovered(): Promise<Discovery> {
262	    this.discovery ??= await discover(this.pdsUrl);
263	    return this.discovery;
264	  }
265	
266	  /** True if the assertion in the cache is present and unexpired. */
267	  private assertionValid(): boolean {
268	    if (!this.creds?.assertion) return false;
269	    try {
270	      const exp = decodeJwtPayload(this.creds.assertion).exp;
271	      return typeof exp === 'number' && exp * 1000 > Date.now() + 10_000;
272	    } catch {
273	      return false;
274	    }
275	  }
276	
277	  status(): SessionState {
278	    if (this.creds?.revoked) return { state: 'revoked' };
279	    if (this.onboarding) {
280	      return {
281	        state: 'onboarding',
282	        userCode: this.onboarding.userCode,
283	        verificationUri: this.onboarding.verificationUri,
284	        expiresAt: this.onboarding.expiresAt,
285	      };
286	    }
287	    if (this.onboardingError) return { state: 'error', message: this.onboardingError };
288	    if (this.assertionValid()) {
289	      return {
290	        state: 'ready',
291	        did: this.creds!.did ?? '(unknown)',
292	        scopes: this.creds!.scopes ?? [],
293	        registrationId: this.creds!.registrationId ?? null,
294	      };
295	    }
296	    if (this.creds?.assertion) return { state: 'expired' };
297	    return { state: 'error', message: 'not onboarded yet' };
298	  }
299	
300	  /** Whether startup needs to run a claim ceremony. */
301	  needsOnboarding(): boolean {
302	    return !this.creds?.revoked && !this.assertionValid();
303	  }
304	
305	  /**
306	   * Run registration (fails fast and legibly when the PDS has agent auth
307	   * disabled), then poll for the human confirmation in the background.
308	   * Returns after registration; `onReady`/`onFailed` fire from the poll loop.
309	   */
310	  async startOnboarding(callbacks: {
311	    onWaiting: (reg: RegistrationResult) => void;
312	    onReady: (state: SessionState) => void;
313	    onFailed: (err: Error) => void;
314	  }): Promise<void> {
315	    const email = loginEmail();
316	    if (!email) {
317	      throw new Error(
318	        'CUSTOS_MCP_EMAIL is not set. First-run onboarding registers this agent against ' +
319	          'your account by email — set it in the MCP server config (see tools/mcp/README.md).',
320	      );
321	    }
322	
323	    const discovery = await this.discovered();
324	    // Complete the spec's discovery walk: the skill document is the prose
325	    // half of the contract. We don't parse it, but a server that fails to
326	    // serve it is worth flagging before we register.
327	    if (discovery.skill) {
328	      try {
329	        await request(discovery.skill);
330	      } catch (err) {
331	        process.stderr.write(
332	          `[custos-mcp] warning: ${discovery.skill} is advertised but not readable ` +
333	            `(${err instanceof Error ? err.message : err})\n`,
334	        );
335	      }
336	    }
337	    const registration = await registerServiceAuth(discovery, email);
338	    this.onboarding = registration;
339	    this.onboardingError = null;
340	    callbacks.onWaiting(registration);
341	
342	    void pollClaim(discovery, registration.claimToken)
343	      .then((granted) => {
344	        const payload = decodeJwtPayload(granted.assertion);
345	        this.creds = {
346	          pdsUrl: this.pdsUrl,
347	          registrationId: registration.registrationId,
348	          assertion: granted.assertion,
349	          accessToken: granted.accessToken,
350	          accessTokenExpiresAt: Math.floor(Date.now() / 1000) + granted.expiresIn,
351	          scopes: granted.scope ? granted.scope.split(' ') : [],
352	          did: typeof payload.sub === 'string' ? payload.sub : undefined,
353	        };
354	        saveCredentials(this.creds);
355	        this.onboarding = null;
356	        callbacks.onReady(this.status());
357	      })
358	      .catch((err: Error) => {
359	        this.onboarding = null;
360	        if (err instanceof RevokedError) {
361	          // A revocation mid-ceremony (the owner declined) is remembered even
362	          // with no prior credential cache, so a restart cannot quietly start
363	          // a fresh registration.
364	          this.creds = { ...(this.creds ?? { pdsUrl: this.pdsUrl }), revoked: true };
365	          saveCredentials(this.creds);
366	        }
367	        this.onboardingError = err.message;
368	        callbacks.onFailed(err);
369	      });
370	  }
371	
372	  /**
373	   * A live access token for tool calls. Re-exchanges the assertion when the
374	   * cached token is missing or within 30s of expiry.
375	   */
376	  async accessToken(): Promise<string> {
377	    if (this.creds?.revoked) throw new RevokedError();
378	    if (this.onboarding) {
379	      throw new Error(
380	        `Onboarding is not finished: ask the account owner to confirm claim code ` +
381	          `${this.onboarding.userCode} at ${this.onboarding.verificationUri} (or in the ` +
382	          `Obsign wallet), then try again.`,
383	      );
384	    }
385	    if (!this.creds?.assertion) {
386	      throw new Error(
387	        this.onboardingError
388	          ? `Onboarding failed: ${this.onboardingError}`
389	          : 'No credentials for this PDS yet — restart the MCP server to onboard.',
390	      );
391	    }
392	    if (!this.assertionValid()) throw new SessionExpiredError();
393	
394	    const now = Math.floor(Date.now() / 1000);
395	    if (this.creds.accessToken && (this.creds.accessTokenExpiresAt ?? 0) > now + 30) {
396	      return this.creds.accessToken;
397	    }
398	
399	    const discovery = await this.discovered();
400	    try {
401	      const token = await exchangeAssertion(
402	        discovery.tokenEndpoint,
403	        this.creds.assertion,
404	        this.pdsUrl,
405	      );
406	      this.creds.accessToken = token.accessToken;
407	      this.creds.accessTokenExpiresAt = now + token.expiresIn;
408	      this.creds.scopes = token.scope ? token.scope.split(' ') : this.creds.scopes;
409	      saveCredentials(this.creds);
410	      return token.accessToken;
411	    } catch (err) {
412	      if (err instanceof RevokedError) {
413	        this.creds.revoked = true;
414	        this.creds.accessToken = undefined;
415	        this.creds.accessTokenExpiresAt = undefined;
416	        saveCredentials(this.creds);
417	      }
418	      throw err;
419	    }
420	  }
421	
422	  /** The DID this session acts as, once onboarded. */
423	  did(): string | null {
424	    return this.creds?.did ?? null;
425	  }
426	
427	  scopes(): string[] {
428	    return this.creds?.scopes ?? [];
429	  }
430	
431	  /** Explicit user action: forget everything about this PDS. */
432	  reset(): void {
433	    clearCredentials(this.pdsUrl);
434	    this.creds = null;
435	    this.onboarding = null;
436	    this.onboardingError = null;
437	  }
438	}
