11	/// Collect `EZPDS_*` env vars, `PORT`, and selected OTel standard vars from the process environment,
12	/// rejecting any with non-UTF-8 values rather than panicking.
13	pub fn collect_ezpds_env() -> Result<HashMap<String, String>, ConfigError> {
14	    let mut map = HashMap::new();
15	    for (key_os, val_os) in std::env::vars_os() {
16	        let key = match key_os.to_str() {
17	            Some(k) if k.starts_with("EZPDS_") || OTEL_ENV_KEYS.contains(&k) || k == "PORT" => {
18	                k.to_owned()
19	            }
20	            _ => continue,
21	        };
22	        let val = val_os.into_string().map_err(|_| {
23	            ConfigError::Invalid(format!(
24	                "environment variable {key} contains non-UTF-8 data"
25	            ))
26	        })?;
27	        map.insert(key, val);
28	    }
29	    Ok(map)
30	}
