32	/// Load [`Config`] from a TOML file with an explicit environment map.
33	///
34	/// This is a public API that accepts an explicit environment map instead of reading from
35	/// the process environment. Useful for tests (passing a controlled environment without
36	/// leaking real `EZPDS_*` vars) and for containerized deployments where the environment
37	/// has already been collected before calling this function.
38	pub fn load_config_with_env(
39	    path: &Path,
40	    env: &HashMap<String, String>,
41	) -> Result<Config, ConfigError> {
42	    let contents = std::fs::read_to_string(path).map_err(|source| ConfigError::Io {
43	        path: path.to_owned(),
44	        source,
45	    })?;
46	    let raw: RawConfig = toml::from_str(&contents)?;
47	    let raw = apply_env_overrides(raw, env)?;
48	    validate_and_build(raw)
49	}
