51	/// Load [`Config`] from a TOML file, applying `EZPDS_*` environment variable overrides.
52	pub fn load_config(path: &Path) -> Result<Config, ConfigError> {
53	    let env = collect_ezpds_env()?;
54	    load_config_with_env(path, &env)
55	}
